import heapq

def match(orders):
    trades = []
    book = {}  # id -> [side, price, qty, seq]
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def clean_buy_heap():
        while buy_heap:
            negprice, seq, oid = buy_heap[0]
            if oid not in book or book[oid][3] != seq:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell_heap():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            if oid not in book or book[oid][3] != seq:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        oid = order[1]
        side = order[2]

        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell_heap()
                if not sell_heap:
                    break
                sp, sseq, soid = sell_heap[0]
                if typ != 'market' and sp > price:
                    break
                resting = book[soid]
                resting_qty = resting[2]
                trade_qty = min(remaining, resting_qty)
                trades.append([oid, soid, sp, trade_qty])
                remaining -= trade_qty
                resting[2] -= trade_qty
                if resting[2] == 0:
                    del book[soid]
                    heapq.heappop(sell_heap)
                # if partially filled, keep in book, seq matches so heap top still valid next loop
            if typ == 'limit' and remaining > 0:
                book[oid] = ['buy', price, remaining, seq_counter]
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
                seq_counter += 1
            else:
                seq_counter += 1
        else:  # sell
            while remaining > 0:
                clean_buy_heap()
                if not buy_heap:
                    break
                negbp, bseq, boid = buy_heap[0]
                bp = -negbp
                if typ != 'market' and bp < price:
                    break
                resting = book[boid]
                resting_qty = resting[2]
                trade_qty = min(remaining, resting_qty)
                trades.append([boid, oid, bp, trade_qty])
                remaining -= trade_qty
                resting[2] -= trade_qty
                if resting[2] == 0:
                    del book[boid]
                    heapq.heappop(buy_heap)
            if typ == 'limit' and remaining > 0:
                book[oid] = ['sell', price, remaining, seq_counter]
                heapq.heappush(sell_heap, (price, seq_counter, oid))
                seq_counter += 1
            else:
                seq_counter += 1

    return trades

